const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = formatMoney;
const numeric = v => v!=='' && v!==null && v!==undefined && Number.isFinite(Number(v)) ? Number(v) : null;
const fmt = v => typeof v==='number' ? formatNumber(v) : String(v??'');
const date = v => {const d=new Date(v);return Number.isFinite(d.getTime())?d.toLocaleString('bs-BA'):'';};
const uid = () => crypto.randomUUID();
const clone = v => JSON.parse(JSON.stringify(v));
const runtime = new ToolsRuntime();
const bridge = new OBDBridge({onStatus:s=>{deviceStatus=typeof s==='string'?s:s.message||s.status||'Promjena veze';updateDeviceStatus();}});
let active=null, tool=null, tab='diagnostic', dirty=false, saveTimer, noticeTimer, deviceStatus='Nije povezano', deviceResult=null, modalReturn=null, diagnosticPanel=null, deviceGeneration=0;
const workspace=$('#workspace'), landing=$('#landing'), modal=$('#modal');
const deviceCenter=new DeviceCenter($('#device-center'),{notice:notify});
const investigationWorkbench=new InvestigationWorkbench($('#investigation-workbench'),{getCases:()=>runtime.listCases()});
const toolComposer=new ToolComposer($('#tool-composer'),{getCases:()=>runtime.listCases()});
const bilLab=new BILLab($('#bil-lab'),{getSnapshots:()=>[],getCases:()=>runtime.listCases()});
const vehicleWorkbench=new VehicleWorkbench($('#vehicle-workbench'));
const pillarText=[['Koordinacija','Ograničen i provjerljiv tok radnji.'],['Povezivanje','Provjereni ulazi i podržani uređaji.'],['Proširenja','Provjereni dijagnostički profili i verzije ugovora.'],['Oporavak','Očuvan predmet kada operacija zakaže.'],['Interakcija','Isti podaci kroz sve radne prikaze.'],['Alternativa','Izvoz i rad u memoriji kad spremanje nije moguće.'],['Uvid','Trag stvarnih radnji i izolovane usporedbe.']];
const landingCopy={auto:'Povežite OBD adapter, pratite kanale vozila kroz vrijeme i uporedite servisne snimke uz izvor svakog nalaza.',electric:'Povežite podržan mjerni izvor i analizirajte naponske, strujne i temperaturne tragove kroz isti postupak.',build:'Pratite vremenske promjene vlage, temperature i dimenzija te povežite mjerna mjesta s radovima na objektu.',climate:'Povežite dostupna očitanja okoline, temperatura i protoka. Sačuvajte referencu i uporedite učinak zahvata.',workshop:'Pratite promjene procesa kroz podržana očitanja vibracija, temperature, potrošnje i dimenzija proizvoda.'};

function notify(message,error=false){const n=$('#notice');n.textContent=message;n.className='notice'+(error?' error':'');n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.hidden=true,error?12000:5500);}
function attempt(fn){try{const result=fn();return result&&typeof result.then==='function'?result.catch(e=>{notify(e.message||'Radnja nije uspjela.',true);return null;}):result;}catch(e){notify(e.message||'Radnja nije uspjela.',true);return null;}}
function download(name,text,type='application/json'){return saveTextFile(name,text,type);}
function filename(s){return String(s??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').replace(/[^a-zA-Z0-9_-]/g,'-').replace(/^[^a-zA-Z0-9]+/,'').slice(0,65)||'clea-predmet';}
let legacyImportController=null,legacyImportGeneration=0;
function cancelLegacyImport(){++legacyImportGeneration;legacyImportController?.abort();legacyImportController=null;}
function applyImportedCase(text){const imported=runtime.importCase(text);modal.close();openTool(imported.toolId,imported.id);notify('Uvezen je novi nezavisni predmet. Original nije prepisan.');}
async function importNativeDraft(){if(dirty&&!save(false))return;cancelLegacyImport();const generation=legacyImportGeneration,route=location.hash,controller=legacyImportController=new AbortController();try{const file=await openNativeText('json',{signal:controller.signal});if(controller.signal.aborted||generation!==legacyImportGeneration||location.hash!==route)return;applyImportedCase(file.text);}finally{if(legacyImportController===controller)legacyImportController=null;}}
function invalidateDevice(){++deviceGeneration;bridge.disconnect();}
function openModal(title,body,eyebrow='BL CLEA TOOLS'){investigationWorkbench.stop();deviceCenter.cancel();deviceCenter.audio.stop();diagnosticPanel?.stop();diagnosticPanel?.disconnectSources();invalidateDevice();if(dirty)save(false);modalReturn=document.activeElement;$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=body;if(!modal.open)modal.showModal();}
function updateCount(){$('#case-count').textContent=runtime.listCases().length;}
function stateLabel(){const n=$('#save-state');if(n){n.textContent=dirty?'Nespremljene izmjene':runtime.persistence.available?'Spremljeno na ovom uređaju':'Samo u memoriji — izvezite predmet';n.className='save-state'+(dirty?' dirty':runtime.persistence.available?'':' error');}const warning=$('#persistence-warning');if(warning){warning.hidden=runtime.persistence.available;warning.textContent=runtime.persistence.message;}const choice=$('#case-select');if(choice&&active){const option=[...choice.options].find(o=>o.value===active.id);if(option)option.textContent=active.title;}updateCount();}
function markDirty(){dirty=true;stateLabel();clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(false),700);}
function save(show=true){clearTimeout(saveTimer);if(!active)return true;const invalid=$$('[data-row], [data-group="record"], [data-group="fields"], [data-group="measurements"]',workspace).find(n=>typeof n.checkValidity==='function'&&!n.checkValidity());if(invalid){invalid.reportValidity();notify('Ispravite označeno polje prije spremanja ili promjene prikaza.',true);return false;}if(!dirty){if(show)notify(runtime.persistence.available?'Predmet je već spremljen.':runtime.persistence.message,!runtime.persistence.available);return true;}try{active=runtime.saveCase(active);dirty=false;stateLabel();if(show)notify(runtime.persistence.available?'Predmet je spremljen.':runtime.persistence.message,!runtime.persistence.available);return true;}catch(e){stateLabel();notify(e.message+' Izvezite nacrt prije ponovnog učitavanja.',true);return false;}}
function fieldHTML(f,value='',prefix='field',group='fields'){const name=`${prefix}-${f.id}`;const attributes=`id="${esc(name)}" data-group="${esc(group)}" data-key="${esc(f.id)}"${group==='record'&&f.id==='title'?' required':''}${f.type==='number'?' inputmode="decimal" step="any"':''}${f.min!==undefined?` min="${esc(f.min)}"`:''}${f.max!==undefined?` max="${esc(f.max)}"`:''}${f.required?' data-required="true"':''}`;let control;if(f.type==='textarea')control=`<textarea ${attributes} maxlength="10000" rows="3">${esc(value)}</textarea>`;else if(f.type==='select')control=`<select ${attributes}><option value="">Odaberite…</option>${(f.options||[]).map(o=>`<option value="${esc(o)}"${value===o?' selected':''}>${esc(o)}</option>`).join('')}</select>`;else control=`<input ${attributes} type="${f.type||'number'}" value="${esc(value)}" maxlength="${group==='record'&&f.id==='title'?160:1000}">`;return `<label class="field${f.type==='textarea'?' full':''}" for="${esc(name)}"><span>${esc(f.label)}${f.unit?` <span class="unit">${esc(f.unit)}</span>`:''}${f.required?' <span aria-label="potrebno za potpun izvještaj">*</span>':''}</span>${control}${f.help?`<small>${esc(f.help)}</small>`:''}</label>`;}
function heading(title,text='',actions=''){return `<div class="panel-heading"><div><h2>${esc(title)}</h2>${text?`<p>${esc(text)}</p>`:''}</div>${actions?`<div class="toolbar">${actions}</div>`:''}</div>`;}
function button(action,label,ico='',classes='secondary',extra=''){return `<button class="button ${classes}" data-action="${action}" ${extra}>${ico?icon(ico,15):''}${esc(label)}</button>`;}

function renderHome(){bilLab.deactivate();vehicleWorkbench.deactivate();toolComposer.deactivate();investigationWorkbench.deactivate();deviceCenter.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;landing.hidden=false;workspace.hidden=true;document.title='CLEA Auto — by Brzo i Lokalno';}
function openDeviceCenter(){bilLab.deactivate();vehicleWorkbench.deactivate();if(active&&dirty&&!save(false))return;toolComposer.deactivate();investigationWorkbench.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;landing.hidden=true;workspace.hidden=true;deviceCenter.activate();$('#device-center').scrollIntoView({block:'start'});}
function openInvestigation(){bilLab.deactivate();vehicleWorkbench.deactivate();if(active&&dirty&&!save(false))return;toolComposer.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;deviceCenter.deactivate();landing.hidden=true;workspace.hidden=true;investigationWorkbench.activate();$('#investigation-workbench').scrollIntoView({block:'start'});}
function openComposer(){bilLab.deactivate();vehicleWorkbench.deactivate();if(active&&dirty&&!save(false))return;invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;deviceCenter.deactivate();investigationWorkbench.deactivate();landing.hidden=true;workspace.hidden=true;toolComposer.activate();$('#tool-composer').scrollIntoView({block:'start'});}
function openBILLab(){if(active&&dirty&&!save(false))return;vehicleWorkbench.deactivate();toolComposer.deactivate();investigationWorkbench.deactivate();deviceCenter.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;landing.hidden=true;workspace.hidden=true;bilLab.activate();$('#bil-lab').scrollIntoView({block:'start'});}
function openVehicle(){if(active&&dirty&&!save(false))return;bilLab.deactivate();toolComposer.deactivate();investigationWorkbench.deactivate();deviceCenter.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;landing.hidden=true;workspace.hidden=true;vehicleWorkbench.activate();$('#vehicle-workbench').scrollIntoView({block:'start'});}
function renderLanding(){ $('#tools-grid').innerHTML=TOOLS.map((t,i)=>`<article class="tool-card" style="--tool:${esc(t.color)}"><div class="tool-card-top"><div class="profession-icon">${icon(t.icon||t.id,29)}</div><span class="tool-number">0${i+1} / CLEA</span></div><h3>${esc(t.name)}</h3><p>${esc(landingCopy[t.id]||t.description||t.tagline)}</p><span class="audience">${esc(t.audience)}</span><div class="card-actions"><button class="button open-tool" data-open="${t.id}">Open Tool ${icon('arrow',14)}</button><button class="button quiet" data-preview="${t.id}">Preview Workflow ${icon('play',12)}</button></div></article>`).join('');$('#pillar-list').innerHTML=PILLARS.map((p,i)=>`<div class="pillar"><span>0${i+1}</span><div><strong>${esc(p.name)}</strong><small>${esc(pillarText[i][1])}</small></div></div>`).join('');}
function openTool(id,caseId){bilLab.deactivate();vehicleWorkbench.deactivate();if(active&&dirty&&!save(false))return;toolComposer.deactivate();investigationWorkbench.deactivate();deviceCenter.deactivate();invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;tool=getTool(id);if(!tool)return;active=caseId?runtime.getCase(caseId):runtime.listCases().filter(c=>c.toolId===id).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt))[0];if(!active)active=runtime.createCase(id,`${tool.shortName||tool.name} · novi predmet`);dirty=false;tab='diagnostic';deviceResult=null;landing.hidden=true;workspace.hidden=false;location.hash='tool/'+id;renderWorkspace();workspace.scrollIntoView({block:'start'});}
function renderWorkspace(){if(!active||!tool)return;document.title=`${tool.name} — BL CLEA Tools`;const related=runtime.listCases().filter(c=>c.toolId===tool.id).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));workspace.innerHTML=`<div class="workspace-top"><div class="workspace-brand"><div class="profession-icon" style="--tool:${esc(tool.color)}">${icon(tool.icon||tool.id,28)}</div><div><p class="eyebrow">BL CLEA TOOLS / RADNI PROSTOR</p><h1 id="workspace-title">${esc(tool.name)}</h1><p>${esc(tool.tagline)}</p></div></div><div class="toolbar">${button('new','Novi predmet','plus','primary')}${button('export','Izvezi','download')}${button('import','Uvezi','upload')}</div></div><div id="persistence-warning" class="persistence-warning" hidden></div><div class="case-bar"><label for="case-select">Radni predmet</label><select id="case-select">${related.map(c=>`<option value="${c.id}"${c.id===active.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select>${button('save','Spremi','save','quiet')}<span id="save-state" class="save-state"></span></div><div class="workspace-layout"><nav class="workspace-tabs" aria-label="Dijelovi radnog predmeta">${[['diagnostic','Živa dijagnostika','activity'],['case','Predmet','file'],['workflow','Postupak','check'],['measurements','Mjerenja','activity'],['calculators','Proračuni','tool'],['quote','Materijal i rad','tool'],...(tool.id==='auto'?[['device','OBD veza','bluetooth']]:[]),['shadow','Usporedi odluku','copy'],['trace','Trag radnji','clock'],['report','Izvještaj','file']].map(([id,label,ico])=>`<button data-tab="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}">${icon(ico,16)}${label}</button>`).join('')}</nav><div class="content-panel" id="tab-content"></div></div>`;renderTab();stateLabel();}
function setTab(id){if(!save(false))return;tab=id;$$('[data-tab]',workspace).forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-current',b.dataset.tab===id?'page':'false');});renderTab();}
function renderTab(){if(tab!=='device')invalidateDevice();diagnosticPanel?.destroy();diagnosticPanel=null;const panel=$('#tab-content');if(!panel)return;if(tab==='diagnostic'){panel.innerHTML='';diagnosticPanel=new DiagnosticPanel(panel,{toolId:tool.id,session:active.diagnostics,relatedCases:runtime.listCases().filter(c=>c.id!==active.id&&c.diagnostics?.frames?.length),onSession:s=>{active.diagnostics=s;markDirty();},onNotice:notify,onTrace:operation=>attempt(()=>runtime.trace(active.id,operation,{pillar:'vision',summary:'Izvršena lokalna dijagnostička radnja.'}))});return;}const views={case:caseView,workflow:workflowView,measurements:measurementsView,calculators:calculatorsView,quote:quoteView,device:deviceView,shadow:shadowView,trace:traceView,report:reportView};panel.innerHTML=(views[tab]||caseView)();if(tab==='device')updateDeviceStatus();}
function caseView(){return heading('Svaki posao počinje jasnom slikom','Opišite zadatak i sačuvajte ono što je važno za nastavak.')+`<div class="field-grid">${fieldHTML({id:'title',label:'Naziv radnog predmeta',type:'text',required:true},active.title,'case','record')}${fieldHTML({id:'client',label:'Klijent / organizacija',type:'text'},active.fields.client,'case')}${fieldHTML({id:'location',label:'Lokacija / oznaka radnog mjesta',type:'text'},active.fields.location,'case')}${fieldHTML({id:'reference',label:'Vaša referentna oznaka',type:'text'},active.fields.reference,'case')}${tool.fields.filter(f=>!['client','location','reference'].includes(f.id)).map(f=>fieldHTML(f,active.fields[f.id],'case')).join('')}${fieldHTML({id:'notes',label:'Bilješke i dogovorene radnje',type:'textarea',help:'Ne unosite lozinke, API ključeve ili podatke koji nisu potrebni za ovaj posao.'},active.notes,'case','record')}</div><p class="form-note">Izmjene se automatski spremaju na ovom uređaju. Za kopiju na drugom uređaju koristite Izvezi → Uvezi. Lokalni radni predmet nije zamjena za službenu evidenciju propisanu za vaše zanimanje.</p><div class="reset-section">${button('delete','Izbriši ovaj predmet','trash','danger')}</div>`;}
function workflowView(){const done=tool.steps.filter(s=>active.steps[s.id]?.done).length;return heading('Postupak povezan s nalazima','Vi potvrđujete izvedene radnje. Alat ne potvrđuje sigurnost uređaja ili instalacije.')+`<div class="step-status"><progress max="${tool.steps.length}" value="${done}"></progress><span id="steps-complete">${done} / ${tool.steps.length} zabilježenih koraka</span></div>${tool.steps.map((s,i)=>`<section class="step-card"><label class="step-check"><input type="checkbox" data-step="${s.id}"${active.steps[s.id]?.done?' checked':''}><strong>${i+1}. ${esc(s.title)}</strong></label><p>${esc(s.description)}</p><label class="field"><span>Nalaz / dokaz izvedene radnje${s.evidenceRequired?' · potreban prije označavanja':''}</span><textarea data-step-note="${s.id}" maxlength="10000" placeholder="Zabilježite šta ste stvarno ustanovili ili uradili.">${esc(active.steps[s.id]?.note||'')}</textarea></label></section>`).join('')}`;}
function measurementsView(){return heading('Mjerenje je dokaz. Pretpostavka nije.','Unesite stvarno očitane vrijednosti i njihov kontekst. Nedostajuće vrijednosti ostaju prazne.')+`<div class="field-grid">${tool.measurements.map(f=>fieldHTML(f,active.measurements[f.id],'measurement','measurements')).join('')}${fieldHTML({id:'measurementContext',label:'Uslovi mjerenja / instrument / vrijeme',type:'textarea',help:'Zapišite radno stanje, instrument i okolnosti zbog kojih se mjerenja mogu razlikovati.'},active.fields.measurementContext,'measurement')}</div>${tool.id==='auto'?`<p class="form-note">Podržan BLE OBD adapter možete povezati u odjeljku OBD veza. Ručni unos i očitanja s adaptera nisu automatska potvrda uzroka kvara.</p>${button('auto-findings','Pregledaj dostupne nalaze','activity','secondary') }<div id="auto-findings"></div>`:''}`;}
function calculatorsView(){return heading('Proračuni s vidljivim pretpostavkama','Unesite vrijednosti. Svaki rezultat ostaje vezan za ovaj predmet kad ga spremite.')+tool.calculators.map(c=>`<form class="calc-card" data-calculator="${c.id}" novalidate><h3>${esc(c.name)}</h3><p>${esc(c.description)}</p><div class="field-grid">${c.inputs.map(f=>fieldHTML(f,'','calc-'+c.id,'calculator')).join('')}</div><button type="submit" class="button primary">Izračunaj ${icon('arrow',15)}</button><div class="calc-output" data-calc-output="${c.id}" hidden aria-live="polite"></div></form>`).join('')+`<p class="form-note">Rezultati služe za planiranje uz navedene uslove i vaše ulazne podatke. Ne predstavljaju projekat, atest ili potvrdu usklađenosti s propisima.</p>`;}
function totals(record=active){const material=record.materials.reduce((n,r)=>n+r.quantity*r.unitPrice,0),work=record.services.reduce((n,r)=>n+r.quantity*r.unitPrice,0);return {material,work,total:material+work};}
function quoteView(){return heading('Materijal i rad','Valuta je oznaka vašeg obračuna. Cijene su bez automatskog poreza ili propisane tarife.')+`<div class="field-grid">${fieldHTML({id:'currency',label:'Valuta / obračunska jedinica',type:'select',options:['BAM','EUR','USD']},active.fields.currency||'BAM','quote')}</div><h3 class="panel-subheading">Materijal i dijelovi</h3><div id="materials-table">${rowsTable('materials')}</div>${button('add-material','Dodaj materijal','plus','secondary')}<h3 class="panel-subheading">Rad i usluge</h3><div id="services-table">${rowsTable('services')}</div>${button('add-service','Dodaj rad / uslugu','plus','secondary')}<div id="quote-total">${totalsHTML()}</div><div class="toolbar">${button('csv','Preuzmi stavke · CSV','download')}${button('show-report','Pripremi izvještaj','file')}</div>`;}
function rowsTable(kind){const materials=kind==='materials';if(!active[kind].length)return `<p class="help">Još nema stavki. Dodajte svoje količine i cijene.</p>`;return `<div class="table-wrap"><table class="edit-table"><thead><tr><th>${materials?'Materijal / dio':'Rad / usluga'}</th><th>Količina</th>${materials?'<th>Jedinica</th>':''}<th>Cijena / jed.</th><th>Ukupno</th><th><span class="small-label">Ukloni</span></th></tr></thead><tbody>${active[kind].map((r,i)=>`<tr><td><input aria-label="${materials?'Naziv materijala':'Opis usluge'} ${i+1}" data-row="${r.id}" data-kind="${kind}" data-prop="${materials?'name':'description'}" value="${esc(materials?r.name:r.description)}" maxlength="300"></td><td class="number"><input type="number" min="0" step="any" aria-label="Količina ${i+1}" data-row="${r.id}" data-kind="${kind}" data-prop="quantity" value="${r.quantity}"></td>${materials?`<td class="number"><input aria-label="Jedinica ${i+1}" data-row="${r.id}" data-kind="${kind}" data-prop="unit" value="${esc(r.unit)}" maxlength="30"></td>`:''}<td class="number"><input type="number" min="0" step="any" aria-label="Jedinična cijena ${i+1}" data-row="${r.id}" data-kind="${kind}" data-prop="unitPrice" value="${r.unitPrice}"></td><td class="sum" data-row-total="${r.id}">${money(r.quantity*r.unitPrice)}</td><td><button class="icon-button" data-remove-row="${r.id}" data-kind="${kind}" aria-label="Ukloni stavku ${i+1}">${icon('trash',15)}</button></td></tr>`).join('')}</tbody></table></div>`;}
function totalsHTML(record=active){const t=totals(record),currency=esc(record.fields.currency||'BAM');return `<div class="quote-total"><div>Materijal<b>${money(t.material)} ${currency}</b></div><div>Rad<b>${money(t.work)} ${currency}</b></div><div class="grand">Ukupno bez poreza<b>${money(t.total)} ${currency}</b></div></div>`;}
function shadowView(){return heading('Prvo uporedite. Tek onda odlučite.','Izolovana usporedba mijenja kopiju obračuna. Vaš stvarni predmet i cijene ostaju netaknuti.')+`<form id="shadow-form"><div class="field-grid">${fieldHTML({id:'percent',label:'Promjena cijene materijala',type:'number',unit:'%',min:-100,max:1000,help:'Npr. 10 za poskupljenje od 10%, ili -5 za popust od 5%.'},'','shadow','shadow')}</div><button type="submit" class="button primary">Uporedi na kopiji ${icon('copy',15)}</button></form><div id="shadow-output" aria-live="polite"></div><p class="form-note">Usporedba koristi postojeće količine i cijene iz Materijal i rad. Ne šalje podatke AI modelu i ne predviđa tržišne cijene.</p>`;}
function traceView(){const events=runtime.explain(active.id);return heading('Trag stvarnih radnji','Vrijeme i ishodi lokalnih operacija. Trag ne izlaže sadržaj vaših bilješki.')+`<p class="help">${events.length} evidentiranih lokalnih događaja. Ovo je pregled rada, nije neizmjenjiv ili službeno ovjeren dnevnik.</p><ol class="timeline">${events.slice(-60).reverse().map(e=>`<li><strong>${esc(e.summary||e.operation)}</strong><time>${esc(date(e.at))} · ${esc(PILLARS.find(p=>p.id===e.pillar)?.name||e.pillar)} · ${esc(e.status)}</time>${e.details?`<pre>${esc(JSON.stringify(e.details,null,2))}</pre>`:''}${typeof e.durationMs==='number'?`<span class="small-label">${fmt(e.durationMs)} ms</span>`:''}</li>`).join('')}</ol>`;}
function completeness(){const missing=[];for(const f of tool.fields)if(f.required&&(active.fields[f.id]===undefined||active.fields[f.id]===null||String(active.fields[f.id]).trim()===''))missing.push(f.label);for(const s of tool.steps)if(s.evidenceRequired&&active.steps[s.id]?.done&&!active.steps[s.id]?.note?.trim())missing.push(`Nalaz: ${s.title}`);if(active.materials.some(r=>!r.name.trim())||active.services.some(r=>!r.description.trim()))missing.push('Nazivi stavki obračuna');return missing;}
function reportView(){const n=tool.steps.filter(s=>active.steps[s.id]?.done).length,missing=completeness();return heading('Spremno za predaju, uz vaše nalaze','Izvještaj sadrži unesene podatke, izvedene proračune i vaš zapis rada.')+`<div class="report-summary"><div><small>Postupak</small><strong>${n} / ${tool.steps.length}</strong></div><div><small>Unesenih mjerenja</small><strong>${tool.measurements.filter(f=>active.measurements[f.id]!==undefined&&active.measurements[f.id]!=='').length}</strong></div><div><small>Ukupno bez poreza</small><strong>${money(totals().total)} <small>${esc(active.fields.currency||'BAM')}</small></strong></div></div>${missing.length?`<div class="finding"><h4>Predmet ima nepotpune podatke</h4><p>${missing.map(esc).join(' · ')}</p><p>Izvještaj će biti označen kao nacrt. Dovršite nalaze prije profesionalne predaje.</p></div>`:`<p class="form-note">Provjerite podatke prije predaje. Broj označenih koraka ne znači da je uređaj ili sistem siguran za upotrebu.</p>`}<div class="report-actions">${button('preview-report','Pregled izvještaja','file','primary')}${button('download-report','Preuzmi izvještaj · HTML','download')}${button('export','Sigurnosna kopija · JSON','save')}</div>${active.calculations.length?`<h3 class="panel-subheading">Spremljeni proračuni</h3>${active.calculations.map(c=>`<div class="step-card"><strong>${esc(c.name||'Proračun')}</strong><p>${esc(date(c.createdAt))}</p>${resultHTML(c.result)}<button class="button quiet" data-remove-calculation="${esc(c.id)}">Ukloni ovaj proračun</button></div>`).join('')}`:''}`;}
function deviceView(){return heading('Stvarna očitanja. Kontrolisana veza.','Čitanje podržanog BLE ELM-style OBD adaptera ili uvoz njegovog tekstualnog odgovora.')+`<div class="device-summary"><div id="device-state" class="device-state"><i></i><b id="device-state-text">${esc(deviceStatus)}</b></div><p>Potrebni su kompatibilan BLE OBD adapter s FFE0/FFE1 servisom, dozvola za Bluetooth i podržan preglednik u sigurnom HTTPS okruženju. Ovaj pojedinačni čitač koristi FFE0/FFE1. Za NUS, Bluetooth Classic SPP i USB/serijsku vezu otvorite Živu dijagnostiku. Priključivanje i mjerenje obavljajte dok je vozilo sigurno zaustavljeno.</p><div class="toolbar">${button('connect-obd','Poveži BLE adapter','bluetooth','primary')}${button('disconnect-obd','Prekini vezu','close')}</div></div><div class="field-grid" style="margin-top:22px">${fieldHTML({id:'command',label:'Dozvoljeno očitanje',type:'select',options:['0105','010C','010D','0104','010B','010F','0110','0111','0142','0100','03']},'0105','obd','device')}</div><p class="help">0105 temperatura rashladne tečnosti · 010C obrtaji · 010D brzina · 0142 napon ECU · 03 DTC kodovi. Ovdje nema brisanja grešaka, aktuatorskih testova ili pisanja ECU podataka.</p><div class="toolbar">${button('read-obd','Očitaj adapter','activity','primary')}</div><h3 class="panel-subheading">Uvezite očitan odgovor</h3><label class="field"><span>Tekst s vašeg OBD uređaja</span><textarea id="obd-import" maxlength="8192" placeholder="Odaberite odgovarajuću komandu iznad i zalijepite stvarni odgovor uređaja."></textarea></label><div class="toolbar" style="margin-top:15px">${button('parse-obd','Obradi uneseni odgovor','file')}</div><div id="device-output" aria-live="polite">${deviceResult?deviceResultHTML(deviceResult):''}</div>`;}
function updateDeviceStatus(){const n=$('#device-state-text');if(n)n.textContent=deviceStatus;$('#device-state')?.classList.toggle('connected',bridge.connected&&bridge.state==='ready');const read=$('[data-action="read-obd"]');if(read)read.disabled=!(bridge.connected&&bridge.state==='ready');}
function deviceResultHTML(r){return `<div class="calc-output${r.ok?'':' error'}"><strong>${['bluetooth','obd-ble','obd-serial'].includes(r.source)?'Primljeno s BLE adaptera':'Obrađen ručno unesen odgovor'} · ${esc(r.command)}</strong>${r.capturedAt?`<p>${esc(date(r.capturedAt))}</p>`:''}${r.values?.length?`<div class="device-data">${r.values.map(v=>`<div class="device-value"><small>${esc(v.label)}</small><strong>${esc(fmt(v.value))} <small>${esc(v.unit)}</small></strong></div>`).join('')}</div>`:''}${r.dtcs?.length?`<p>DTC: ${r.dtcs.map(esc).join(', ')}</p>`:''}${r.errors?.length?`<p>${r.errors.map(esc).join(' · ')}</p>`:''}${r.notes?.length?`<p>${r.notes.map(esc).join(' · ')}</p>`:''}${r.ok&&(r.values?.length||r.dtcs?.length)?`<div class="toolbar" style="margin-top:15px">${button('save-obd','Dodaj nalaz u predmet','save','secondary')}</div>`:''}</div><pre class="device-log">${esc(r.raw||'')}</pre>`;}
function findingsHTML(a){return a.findings.map(f=>`<div class="finding"><h4>${esc(f.title)}</h4><p>${esc(Array.isArray(f.evidence)?f.evidence.join('; '):f.evidence)}</p><p>${esc(f.recommendation)}</p></div>`).join('')+`<p class="form-note">${a.limitations.map(esc).join(' ')}</p>`;}
function resultHTML(r){if(!r||!Array.isArray(r.items))return '<p>Nema sačuvanog strukturiranog rezultata.</p>';return `<div class="calc-result-items">${r.items.map(i=>`<div><small>${esc(i.label)}</small><strong>${esc(fmt(i.value))} <small>${esc(i.unit||'')}</small></strong></div>`).join('')}</div>${(r.notes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}`;}

function reportHTML(){const info=[{label:'Naziv',value:active.title},{label:'Alat',value:tool.name},{label:'Klijent / organizacija',value:active.fields.client},{label:'Lokacija',value:active.fields.location},{label:'Referentna oznaka',value:active.fields.reference},...tool.fields.filter(f=>!['client','location','reference'].includes(f.id)).map(f=>({label:f.label,value:active.fields[f.id],unit:f.unit}))];const table=rows=>`<table><tbody>${rows.filter(r=>r.value!==undefined&&r.value!==null&&r.value!=='').map(r=>`<tr><th>${esc(r.label)}</th><td class="preserve">${esc(fmt(r.value))}${r.unit?' '+esc(r.unit):''}</td></tr>`).join('')}</tbody></table>`;const t=totals(),currency=esc(active.fields.currency||'BAM'),missing=completeness();return `<article class="paper"><p class="paper-brand">BL CLEA TOOLS · BY BRZO I LOKALNO</p><h1>${esc(active.title)}</h1><p>${esc(tool.name)} · ${missing.length?'NACRT — nepotpuni podaci':'Radni izvještaj'}<br>Izrađeno: ${esc(date(new Date().toISOString()))} · revizija ${active.revision}<br>Referenca predmeta: ${esc(active.id)}</p>${missing.length?`<p>Potrebno dopuniti: ${missing.map(esc).join('; ')}</p>`:''}<h2>Predmet</h2>${table(info)}${diagnosticReportHTML(active.diagnostics)}<h2>Mjerenja koja je unio korisnik</h2>${table(tool.measurements.map(f=>({label:f.label,value:active.measurements[f.id],unit:f.unit})))}${active.fields.measurementContext?`<p class="preserve">${esc(active.fields.measurementContext)}</p>`:''}${active.fields.obdCapturedAt?`<p>OBD izvor: ${esc(active.fields.obdSource)}; vrijeme: ${esc(date(active.fields.obdCapturedAt))}. Zabilježeno očitanje nije automatska potvrda ispravnosti.</p>`:''}${active.fields.obdDTC?`<p>Zabilježeni DTC kodovi: ${esc(active.fields.obdDTC)}</p>`:''}<h2>Zabilježeni postupak</h2><table><thead><tr><th>Korak</th><th>Status i nalaz korisnika</th></tr></thead><tbody>${tool.steps.map(s=>`<tr><th>${esc(s.title)}</th><td>${active.steps[s.id]?.done?'Korisnik označio izvedenim':'Nije označeno'}<br><span class="preserve">${esc(active.steps[s.id]?.note||'Bez zabilježenog nalaza.')}</span></td></tr>`).join('')}</tbody></table><h2>Materijal i rad · ${currency}</h2><table><thead><tr><th>Stavka</th><th>Količina</th><th>Cijena / jed.</th><th>Iznos</th></tr></thead><tbody>${[...active.materials.map(r=>({...r,label:r.name})),...active.services.map(r=>({...r,label:r.description,unit:'usl.'}))].map(r=>`<tr><td>${esc(r.label||'Neimenovana stavka')}</td><td>${esc(fmt(r.quantity))} ${esc(r.unit)}</td><td>${money(r.unitPrice)}</td><td>${money(r.quantity*r.unitPrice)}</td></tr>`).join('')}</tbody></table><p class="report-totals">Materijal ${money(t.material)} ${currency} · Rad ${money(t.work)} ${currency}<br>Ukupno bez poreza: ${money(t.total)} ${currency}</p>${active.calculations.length?'<h2>Spremljeni proračuni</h2>'+active.calculations.map(c=>`<section><h3>${esc(c.name||'Proračun')}</h3><p>${esc(date(c.createdAt))}</p>${table(Object.entries(c.inputs||{}).map(([k,v])=>({label:k,value:v})))}${table((c.result?.items||[]).map(i=>({label:i.label,value:i.value,unit:i.unit})))}${(c.result?.notes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}</section>`).join(''):''}${active.notes?`<h2>Bilješke</h2><p class="preserve">${esc(active.notes)}</p>`:''}<p class="disclaimer">Izvještaj je generisan iz podataka i potvrda korisnika. Nije atest, automatska dijagnoza, poreski račun ili potvrda sigurnosti/usklađenosti. Mjerenja i zahvate provodi odgovarajuće osposobljena osoba. Prazna ili nepotpuna polja nisu pretpostavljena. Izvještaj ne sadrži digitalni potpis niti zaštitu od naknadne izmjene.</p></article>`;}
async function downloadReport(){if(!save(false))return;const html=`<!doctype html><html lang="bs"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none';style-src 'unsafe-inline';img-src data:;base-uri 'none';form-action 'none'"><title>${esc(active.title)} — CLEA izvještaj</title><style>body{max-width:900px;margin:35px auto;padding:0 20px;color:#192d3e;background:#fff;font:14px/1.7 system-ui,sans-serif}h1{font-size:32px;line-height:1.2}h2{font-size:20px;border-bottom:1px solid #cbd4dc;margin-top:30px}h3{font-size:16px}.paper-brand{font-size:11px;letter-spacing:2px;color:#806a35}table{width:100%;border-collapse:collapse;font-size:12px;margin:15px 0}td,th{text-align:left;vertical-align:top;padding:9px;border-bottom:1px solid #dde4e9;overflow-wrap:anywhere}th{background:#f3f5f7;font-weight:550}.preserve{white-space:pre-wrap}.disclaimer{font-size:11px;border-top:1px solid #dde4e9;margin-top:35px;padding-top:15px}.report-totals{text-align:right;font-weight:600}@media print{@page{size:A4;margin:16mm}body{margin:0;max-width:none;padding:0}tr{break-inside:avoid}h2{break-after:avoid}}</style>${reportHTML()}</html>`;const result=await download(filename(active.title)+'.html',html,'text/html;charset=utf-8');notify(result.native?'Izvještaj je sačuvan u odabranu datoteku.':'Preuzimanje izvještaja je pokrenuto. HTML otvorite za čitanje ili štampu u PDF.');}
async function exportDraft(){if(!active)return;const data=clone(active),result=await download(filename(data.title)+'-clea-tools.json',JSON.stringify(data,null,2));notify(result.native?'Kopija predmeta je sačuvana u odabranu datoteku.':'Preuzimanje lokalne kopije predmeta je pokrenuto.');}
async function exportCSV(){const safe=v=>{let s=String(v??'');if(typeof v!=='number'&&/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const rows=[['Vrsta','Opis','Količina','Jedinica','Jedinična cijena','Ukupno','Valuta'],...active.materials.map(r=>['Materijal',r.name,r.quantity,r.unit,r.unitPrice,r.quantity*r.unitPrice,active.fields.currency||'BAM']),...active.services.map(r=>['Rad',r.description,r.quantity,'usl.',r.unitPrice,r.quantity*r.unitPrice,active.fields.currency||'BAM'])];const result=await download(filename(active.title)+'-stavke.csv','\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n'),'text/csv;charset=utf-8');notify(result.native?'CSV stavke su sačuvane u odabranu datoteku.':'Preuzimanje CSV stavki je pokrenuto.');}
function previewWorkflow(id){const t=getTool(id);if(!t)return;openModal(t.name,`<p>${esc(t.description)}</p><p>Za koga: ${esc(t.audience)}</p><ol class="workflow-preview">${t.steps.map(s=>`<li><div><strong>${esc(s.title)}</strong><p>${esc(s.description)}</p></div></li>`).join('')}</ol><h3>Uključeni proračuni</h3><ul>${t.calculators.map(c=>`<li>${esc(c.name)}</li>`).join('')}</ul><div class="report-actions"><button class="button primary" data-open="${t.id}">Open Tool ${icon('arrow',15)}</button></div>`,'PREGLED STVARNOG TOKA RADA');}
function showLibrary(){if(dirty&&!save(false))return;const cases=runtime.listCases().sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));openModal('Vaši radni predmeti',`<label class="field"><span>Pretražite po nazivu ili alatu</span><input id="library-search" type="search" class="filter-input" placeholder="Naziv predmeta…"></label><div class="library-list">${cases.length?cases.map(c=>`<article class="library-item" data-library-search="${esc((c.title+' '+getTool(c.toolId).name).toLowerCase())}"><span style="color:${esc(getTool(c.toolId).color)}">${icon(c.toolId,24)}</span><div><h3>${esc(c.title)}</h3><p>${esc(getTool(c.toolId).name)} · ${esc(date(c.updatedAt))}</p></div><button class="button secondary" data-load="${c.id}" data-tool="${c.toolId}">Otvori ${icon('arrow',13)}</button></article>`).join(''):'<div class="empty-state"><h3>Vaš prvi posao čeka.</h3><p>Odaberite alat na početnoj stranici i otvorite predmet.</p></div>'}</div><div class="report-actions">${button('import','Uvezi lokalni predmet','upload')}</div><p class="form-note">Predmeti su lokalni za ovaj preglednik. Redovno izvezite kopije, posebno prije čišćenja podataka preglednika.</p>`);}
function aboutDialog(which){const pages={privacy:['Podaci ostaju uz vas',`<p>Sadržaj predmeta, mjerenja i bilješke obrađuju se u vašem pregledniku. Aplikacija nema analitiku, reklamne skripte, udaljenu bazu, AI pozive ili automatsko slanje sadržaja.</p><h3>Lokalno čuvanje</h3><p>Podaci su u localStorage spremištu ovog porijekla. Nisu šifrirani i nisu automatski sinhronizovani. Drugi korisnici istog profila ili zlonamjerne ekstenzije mogu im pristupiti. Koristite zaključan uređaj i izvoz za sigurnosne kopije.</p><h3>Uređaji</h3><p>Birači Bluetooth, USB, HID i serijskih uređaja otvaraju se tek nakon vaše radnje. Puls se pokušava očitati samo uz poseban pristanak za taj pregled. Standardni senzori kretanja uključuju se zasebno za svaki pregled; GPS se ne traži. Audio provjera pušta kratak signal kroz sistemski izlaz, bez pristupa mikrofonu. Snimak uređaja sprema se u historiju samo kada odaberete Sačuvaj. Veza se koristi samo za podržana očitanja; aplikacija ne traži lokaciju, kameru ili pristup datotekama na cijelom uređaju. Za uvoz sami birate jednu datoteku.</p><h3>Hosting</h3><p>Hosting obrađuje standardne zahtjeve za pristup stranici i svoje autentikacijske podatke. Ti zahtjevi ne sadrže sadržaj radnih predmeta. Lokalno brisanje predmeta dostupno je u njegovom odjeljku Predmet. Već izvezene datoteke brišete na svom uređaju.</p>`],about:['Šta alati stvarno rade',`<p>CLEA Auto povezuje podržani ELM adapter, pregled vozila, vođene provjere i lokalni BIL laboratorij. Zajedničko Tools jezgro provjerava dostupne podatke, čuva lokalne zapise i objašnjava nalaze iz njihovih stvarnih izvora. Sve uključene funkcije su besplatne, bez probnog roka, ključa i pretplate.</p><h3>Uključeno</h3><p>BIL laboratorij za lokalne postupke nad numeričkim očitanjima, OBD pregled tri kategorije kodova i statusa provjera, standardni Bluetooth senzori kretanja, radni predmeti, postupci sa zapisanim nalazima, stručni proračuni s navedenim uslovima, obračun materijala i rada, izolovana usporedba troškova, JSON/CSV izvoz i samostalni HTML izvještaji za štampu.</p><h3>Bluetooth OBD kompatibilnost</h3><p>Podržani su izričito odabrani ELM BLE profili FFE0/FFE1 i Nordic UART, uz provjeru ELM odgovora. Android testno izdanje ima ugrađen Bluetooth Classic SPP priključak za ranije uparene kompatibilne adaptere. Na podržanom desktopu SPP i serijski/USB ELM koriste Web Serial. Preglednik mora imati Web Bluetooth API i siguran HTTPS kontekst. Android Chrome i pojedini desktop Chromium preglednici nude ovaj API, ali dostupnost zavisi od uređaja i sistema. Safari, Firefox i proizvoljni ECU protokoli nisu pokriveni. Prisustvo Bluetooth ili Serial API-ja samo po sebi ne potvrđuje kompatibilnost adaptera.</p><p>Očitavanje ne jamči ispravnost ili sigurnost vozila. Fizički OBD adapter i vozilo nisu potvrđeni u ovom razvojnom okruženju. Ručni unos i uvoz su dostupni bez Bluetooth veze.</p><h3>Odnos prema CLEA7</h3><p>Suite slijedi sedam CLEA odgovornosti, uz svoj Tools Runtime. BIL laboratorij koristi postojeći originalni CLEA7 kompajler i Runtime za lokalne mjerne programe. Kompajlira izvor, provjerava tipove i prikazuje stvarni trag izvršavanja. To nije puni Studio niti opći pokretač .clea7 aplikacija. Nema instaliranog AI modela ili upravljanja aktuatorima. Kodovi i vođene provjere sami ne potvrđuju koji dio treba zamijeniti.</p><h3>Rad bez mreže</h3><p>Android APK već sadrži interfejs i BIL te radi lokalno bez dozvole za internet. U njemu se JSON i BIL datoteke biraju i spremaju kroz Androidov sistemski dijalog. Web izdanje nakon uspješnog spremanja aplikacijskih datoteka radi offline na istom uređaju; hosting i inicijalno otvaranje zahtijevaju mrežu. Status offline pripreme prikazuje se u ovom prozoru.</p><p id="offline-status" class="offline-status">${esc(offlineMessage)}</p>`],licenses:['Originalni rad. Jasno porijeklo.',`<p>Vizuelni identitet BL CLEA Tools, SVG grafika, ikone, radni tokovi i programski moduli ove aplikacije izrađeni su za Brzo i Lokalno. Slika iz razgovora služila je kao vizuelni smjer; njeni crteži nisu kopirani niti ugrađeni.</p><p>Aplikacijski paket ne koristi vanjske fontove, fotografije, biblioteke ikona ili runtime biblioteke trećih strana. Koristi standardne mogućnosti preglednika. Testni alati, ako su korišteni, odvojeni su od aplikacijskog paketa.</p><p>Autorska prava na raniji CLEA7 i njegova postojeća licenca nisu izmijenjeni. Originalni CLEA7 BIL kompajler i Runtime ugrađeni su uz zadržane autorske obavijesti. Njihova licenca nije promijenjena; ova stranica zadržava postojeći privatni pristup. Opće formule i standardizovane OBD oznake nisu tvrdnja o ekskluzivnom vlasništvu nad protokolima.</p><p>Nije rađena pravna provjera žiga niti tvrdnja da su postupci prvi na svijetu. Ne tvrdi se nadmoć nad svim drugim profesionalnim alatima. Oznake vozila, proizvođača i opreme ostaju vlasništvo njihovih nosilaca.</p>`]};const [title,body]=pages[which]||pages.about;openModal(title,body);}

document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;if(b.closest('.workspace-menu'))b.closest('.workspace-menu').open=false;if(b.hasAttribute('data-open-library')){showLibrary();return;}if(b.dataset.open){modal.close();attempt(()=>openTool(b.dataset.open));return;}if(b.dataset.preview){previewWorkflow(b.dataset.preview);return;}if(b.dataset.load){modal.close();attempt(()=>openTool(b.dataset.tool,b.dataset.load));return;}if(b.dataset.dialog){aboutDialog(b.dataset.dialog);return;}if(b.dataset.tab){setTab(b.dataset.tab);return;}if(b.dataset.removeCalculation){active.calculations=active.calculations.filter(c=>c.id!==b.dataset.removeCalculation);markDirty();renderTab();return;}if(b.dataset.removeRow){const kind=b.dataset.kind;active[kind]=active[kind].filter(r=>r.id!==b.dataset.removeRow);markDirty();renderTab();return;}const action=b.dataset.action;if(!action)return;
  if(action==='save')save();
  if(action==='new'){if(!save(false))return;openModal('Novi radni predmet',`<form id="new-case-form"><label class="field"><span>Naziv predmeta</span><input name="title" required maxlength="160" placeholder="Npr. Servis porodičnog vozila" autofocus></label><button class="button primary" style="margin-top:20px">Otvori predmet ${icon('plus',15)}</button></form>`,tool.name);}
  if(action==='export')await attempt(exportDraft);
  if(action==='import'){if(hasNativeFiles())await attempt(importNativeDraft);else $('#import-file').click();}
  if(action==='delete')openModal('Izbrisati ovaj predmet?',`<p>Trajno ćete ukloniti <strong>${esc(active.title)}</strong> iz ovog preglednika. Ranije izvezene kopije ostaju na vašem uređaju.</p><div class="report-actions">${button('export','Prvo preuzmi kopiju','download')}${button('confirm-delete','Izbriši predmet','trash','danger')}</div>`);
  if(action==='confirm-delete'){const id=active.id;clearTimeout(saveTimer);if(attempt(()=>{runtime.deleteCase(id);return true;})){active=null;dirty=false;modal.close();location.hash='home';renderHome();updateCount();notify('Predmet je izbrisan iz lokalnog spremišta.');}}
  if(action==='add-material'||action==='add-service'){const k=action==='add-material'?'materials':'services';active[k].push(k==='materials'?{id:uid(),name:'',quantity:1,unit:'kom',unitPrice:0}:{id:uid(),description:'',quantity:1,unitPrice:0});markDirty();renderTab();}
  if(action==='csv')await attempt(exportCSV);
  if(action==='show-report')setTab('report');
  if(action==='preview-report'){if(save(false))openModal('Pregled izvještaja',reportHTML()+`<div class="report-actions">${button('print','Štampaj / Sačuvaj PDF','print','primary')}${button('download-report','Preuzmi HTML','download')}</div>`);}
  if(action==='download-report')await attempt(downloadReport);
  if(action==='print'){const result=await attempt(printCurrentDocument);if(result?.started)notify('Otvoren je sistemski dijalog za štampu ili spremanje PDF-a.');}
  if(action==='connect-obd'){const generation=deviceGeneration,caseId=active.id;b.disabled=true;try{await bridge.connect();if(generation!==deviceGeneration||active?.id!==caseId||tab!=='device')return;deviceStatus='BLE adapter povezan';notify('Veza je uspostavljena. Odaberite očitanje.');}catch(err){if(generation===deviceGeneration){deviceStatus=err.message;notify(err.message,true);}}finally{b.disabled=false;updateDeviceStatus();}}
  if(action==='disconnect-obd'){await bridge.disconnect();deviceStatus='Veza prekinuta';updateDeviceStatus();}
  if(action==='read-obd'){const command=$('#obd-command').value;if(!command){notify('Odaberite očitanje.',true);return;}const generation=deviceGeneration,caseId=active.id;b.disabled=true;try{const result=await bridge.read(command);if(generation!==deviceGeneration||active?.id!==caseId||tab!=='device'||workspace.hidden||modal.open)return;deviceResult=result;const output=$('#device-output');if(output)output.innerHTML=deviceResultHTML(result);}catch(err){if(generation===deviceGeneration)notify(err.message,true);}finally{if(generation===deviceGeneration)updateDeviceStatus();}}
  if(action==='parse-obd'){attempt(()=>{const command=$('#obd-command').value;if(!command)throw Error('Odaberite komandu koja odgovara unesenom odgovoru.');deviceResult={...parseELMResponse(command,$('#obd-import').value),source:'manual-import',capturedAt:new Date().toISOString()};$('#device-output').innerHTML=deviceResultHTML(deviceResult);});}
  if(action==='save-obd'){if(!deviceResult?.ok)return;const r=deviceResult;const map={coolantTemperature:'coolant',rpm:'rpm',speed:'speed',ecuVoltage:'voltage',controlModuleVoltage:'voltage',intakeTemperature:'intakeTemp',engineLoad:'load'};for(const v of r.values||[]){const candidate=tool.measurements.find(f=>f.id===v.id||f.id===map[v.id]);if(candidate)active.measurements[candidate.id]=v.value;}active.fields.obdSource=['bluetooth','obd-ble','obd-serial'].includes(r.source)?'BLE adapter':'Ručni uvoz tekstualnog odgovora';active.fields.obdCapturedAt=r.capturedAt;active.fields.obdDTC=(r.dtcs||[]).join(', ');const lines=(r.values||[]).map(v=>`${v.label}: ${v.value} ${v.unit||''}`);active.notes=[active.notes,`OBD ${r.command} · ${active.fields.obdSource} · ${date(r.capturedAt)}\n${lines.join('\n')}${r.dtcs?.length?'\nDTC: '+r.dtcs.join(', '):''}`].filter(Boolean).join('\n\n');markDirty();if(save(false))notify('Očitanje je dodano predmetu s navedenim izvorom.');}
  if(action==='auto-findings'){const dtcs=(active.fields.obdDTC||'').split(/[,\s]+/).filter(Boolean);$('#auto-findings').innerHTML=findingsHTML(analyzeAuto(active.measurements,dtcs));}
});
document.addEventListener('input',e=>{const n=e.target;if(n.id==='library-search'){const q=n.value.toLocaleLowerCase();$$('[data-library-search]').forEach(r=>r.hidden=!r.dataset.librarySearch.includes(q));return;}if(!active)return;if(n.dataset.stepNote){const id=n.dataset.stepNote;active.steps[id]={done:active.steps[id]?.done||false,note:n.value};if(active.steps[id].done&&!n.value.trim()){active.steps[id].done=false;const c=$(`[data-step="${id}"]`);if(c)c.checked=false;}markDirty();return;}if(n.dataset.row){const r=active[n.dataset.kind].find(r=>r.id===n.dataset.row);if(!r)return;const p=n.dataset.prop;if(n.type==='number'){const val=n.value===''?0:Number(n.value);if(!Number.isFinite(val)||val<0||val>1e12){n.setCustomValidity('Unesite broj između 0 i 1 000 000 000 000.');return;}n.setCustomValidity('');r[p]=val;}else r[p]=n.value;const t=$(`[data-row-total="${r.id}"]`);if(t)t.textContent=money(r.quantity*r.unitPrice);$('#quote-total').innerHTML=totalsHTML();markDirty();return;}const group=n.dataset.group,key=n.dataset.key;if(!group||!['fields','measurements','record'].includes(group))return;let value=n.value;if(n.type==='number'&&value!==''){value=Number(value);if(!Number.isFinite(value)||Math.abs(value)>1e12){n.setCustomValidity('Unesite konačan broj u dozvoljenom rasponu.');return;}n.setCustomValidity('');}if(group==='record'){if(key==='title'&&!value.trim())return;active[key]=value;}else active[group][key]=value;markDirty();});
document.addEventListener('change',e=>{const n=e.target;if(n.id==='case-select'){attempt(()=>openTool(tool.id,n.value));return;}if(n.dataset.step){const id=n.dataset.step,s=tool.steps.find(s=>s.id===id),note=active.steps[id]?.note||'';if(n.checked&&s.evidenceRequired&&!note.trim()){n.checked=false;notify('Prvo zabilježite nalaz ili dokaz izvedene radnje.',true);return;}active.steps[id]={done:n.checked,note};markDirty();const done=tool.steps.filter(s=>active.steps[s.id]?.done).length;$('progress').value=done;$('#steps-complete').textContent=`${done} / ${tool.steps.length} zabilježenih koraka`;}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.id==='new-case-form'){attempt(()=>{if(!save(false))return;const title=new FormData(form).get('title').trim();if(!title)throw Error('Unesite naziv predmeta.');const created=runtime.createCase(tool.id,title);diagnosticPanel?.destroy();diagnosticPanel=null;active=created;dirty=false;modal.close();tab='diagnostic';renderWorkspace();});return;}if(form.dataset.calculator){const c=tool.calculators.find(c=>c.id===form.dataset.calculator),out=$('[data-calc-output]',form);attempt(()=>{const values={};for(const f of c.inputs){const n=$(`[data-key="${f.id}"]`,form);if(f.type==='number'||!f.type){if(n.value.trim()==='')throw Error(`Unesite ${f.label.toLowerCase()}.`);values[f.id]=Number(n.value);}else values[f.id]=n.value;}try{const result=c.calculate(values);if(!result||!Array.isArray(result.items))throw Error('Proračun nije vratio podržan rezultat.');out.hidden=false;out.className='calc-output';out.innerHTML=resultHTML(result)+button('store-calculation','Spremi proračun u predmet','save','secondary');const btn=$('[data-action="store-calculation"]',out);btn.addEventListener('click',()=>{if(active.calculations.length>=100){notify('Predmet može sadržavati najviše 100 proračuna.',true);return;}const next=clone(active);next.calculations.push({id:uid(),name:c.name,inputs:values,result,createdAt:new Date().toISOString()});validateCase(next);active=next;markDirty();if(save(false)){btn.disabled=true;btn.textContent='Spremljeno u predmet';}});}catch(err){out.hidden=false;out.className='calc-output error';out.textContent=err.message;}});return;}if(form.id==='shadow-form'){attempt(()=>{const n=$('#shadow-percent');if(n.value.trim()==='')throw Error('Unesite promjenu cijene u postocima.');const p=Number(n.value);if(!Number.isFinite(p)||p< -100||p>1000)throw Error('Postotak mora biti između -100 i 1000.');if(!active.materials.length)throw Error('Prvo dodajte stvarne stavke materijala.');if(!save(false))return;const result=runtime.runShadow(active,r=>{r.materials.forEach(row=>row.unitPrice=Math.round(row.unitPrice*(1+p/100)*100)/100);return r;}),a=totals(result.before),b=totals(result.after);$('#shadow-output').innerHTML=`<div class="shadow-result"><h3>Izolovana usporedba · ${fmt(p)}%</h3><div class="report-summary"><div><small>Vaš obračun</small><strong>${money(a.total)}</strong></div><div><small>Uspoređena kopija</small><strong>${money(b.total)}</strong></div><div><small>Razlika</small><strong>${money(b.total-a.total)}</strong></div></div><p>${esc(active.fields.currency||'BAM')} · promijenjena samo cijena materijala. Stvarni predmet nije izmijenjen.</p></div>`;});}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>2*1024*1024){notify('Datoteka je veća od 2 MiB.',true);return;}try{if(dirty&&!save(false))return;applyImportedCase(await file.text());}catch(err){notify(err.message,true);}});
$('#library-button').addEventListener('click',showLibrary);$('#close-modal').addEventListener('click',()=>modal.close());modal.addEventListener('close',()=>modalReturn?.focus());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
